+import { $internal } from '../../common';
+import { createModifier } from '../modifier';
+import type { Predicate } from '../types';
+import type { Trait, TraitRecord } from '../../trait/types';
+
+let predicateId = 0;
+
+/** Creates a value-based filter over the supplied non-tag, non-relation traits. */
+export function createPredicate<T extends Trait[]>(
+    traits: T,
+    predicate: (data: { [K in keyof T]: T[K] extends Trait ? TraitRecord<T[K]> : never }) => boolean
+): Predicate<T> {
+    for (const trait of traits) {
+        if (trait[$internal].type === 'tag') {
+            throw new Error('Koota: Predicate dependencies cannot be tags.');
+        }
+        if (trait[$internal].relation) {
+            throw new Error('Koota: Predicate dependencies cannot be relations.');
+        }
+    }
+
+    return Object.assign(createModifier('predicate', predicateId++, traits), { predicate }) as Predicate<T>;
+}
