+export function checkPredicateFilters(world: World, query: QueryInstance, entity: Entity): boolean {
+    for (const predicate of query.predicates) {
+        if (!matchesPredicate(world, entity, predicate)) return false;
+    }
+    for (const predicate of query.negatedPredicates) {
+        if (matchesPredicate(world, entity, predicate)) return false;
+    }
+    if (query.orTraits.length || query.orPredicates.length) {
+        let matches = false;
+        for (const instance of query.orTraits) {
+            if (hasTrait(world, entity, instance.trait)) {
+                matches = true;
+                break;
+            }
+        }
+        if (!matches) {
+            for (const predicate of query.orPredicates) {
+                if (matchesPredicate(world, entity, predicate)) {
+                    matches = true;
+                    break;
+                }
+            }
+        }
+        if (!matches) return false;
+    }
+    return true;
+}
